const rssXml = $('인기 뉴스 조회').first().json.data || $('인기 뉴스 조회').first().json;
const xmlString = typeof rssXml === 'string' ? rssXml : JSON.stringify(rssXml);
const itemBlocks = [...xmlString.matchAll(/<item>([\s\S]*?)<\/item>/g)].map(m => m[1]);

if (itemBlocks.length === 0) {
  throw new Error('뉴스 항목을 찾을 수 없습니다.');
}

const first = itemBlocks[0];
const titleMatch = first.match(/<title>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/title>/);
const linkMatch = first.match(/<link>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/link>/);
const pubDateMatch = first.match(/<pubDate>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/pubDate>/);
const sourceMatch = first.match(/<source[^>]*>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/source>/);

const title = titleMatch ? titleMatch[1] : '제목 없음';
const link = linkMatch ? linkMatch[1] : '';
const pubDate = pubDateMatch ? pubDateMatch[1] : '';
const source = sourceMatch ? sourceMatch[1] : '';

const today = new Date().toLocaleDateString('ko-KR', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' });

const subject = `[오늘의 인기 뉴스] ${title}`;
const html = `<h2>${today} 인기 뉴스</h2><p><b>${title}</b></p><p>출처: ${source}<br/>발행: ${pubDate}</p><p><a href="${link}">${link}</a></p>`;

return [{ json: { title, link, pubDate, source, subject, html } }];
